import { ChangeDetectionStrategy, Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges, computed, effect, signal, untracked } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatTooltipModule } from '@angular/material/tooltip';
import { Subscription } from 'rxjs';
import { IssueService } from '../../../rt/services/issue/issue.service';
import { categoryList, issueListRes } from '../../../rt/interfaces/issue.interface';
import { SelectionActionsService } from '../../../shared/services/selection-actions/selection-actions.service';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

interface IssueGroup {
  nICid: string;
  cCategory: string;
  isUnassigned: boolean;
  issues: issueListRes[];
  /** Fact-side shared sequence (from RClaimMaster) — used as the fallback
   *  ordering when the user has no per-claim QFact pref. */
  nSequence?: number;
  /** Per-user QFact-only claim sequence (from RUserQFactClaimPref via
   *  LEFT JOIN). Drives the LEFT panel's claim order when present. */
  nQFactSequence?: number | null;
}

@Component({
  selector: 'qfact-issue-panel',
  standalone: true,
  imports: [CommonModule, MatTooltipModule],
  templateUrl: './qfact-issue-panel.component.html',
  styleUrl: './qfact-issue-panel.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QFactIssuePanelComponent implements OnInit, OnChanges, OnDestroy {
  @Input() nCaseid!: string;
  @Input() nUserid!: string;
  /** Realtime session id when this panel is mounted in an RT context. The PDF
   *  viewer (individual-doc) doesn't have one, so default to `'null'` matching
   *  the convention used by IssueService.fetchIssueListV2. */
  @Input() nSesid: string = 'null';

  groups = signal<IssueGroup[]>([]);
  loading = signal<boolean>(true);

  /** Default visibility cap when the user hasn't customised which issues
   *  appear in this panel — show the first N issues of every claim, ranked
   *  by Fact-side nSequence. */
  private static readonly DEFAULT_VISIBLE_PER_CLAIM = 2;

  /** True when the case has at least one real (non-Unassigned) issue. Drives
   *  the Unassigned bucket's visibility in this picker — once the user has any
   *  real issue to choose from, the system Unassigned steps out of the way.
   *  Sourced from the raw `groups()` so per-user QFact-visibility prefs on
   *  the real issues don't bring Unassigned back. */
  hasRealIssues = computed<boolean>(() =>
    this.groups().some(g => !g.isUnassigned && g.issues.length > 0)
  );

  /** Groups filtered + sorted by per-user QFact prefs returned from the
   *  backend on each issue (`bQFactVisible`, `nQFactSequence`). The rules:
   *
   *    bQFactVisible === false → hide
   *    bQFactVisible === true  → show
   *    bQFactVisible == null   → default rule: show iff among the first N of
   *                              its claim by nSequence (no pref yet)
   *
   *  Within a claim, prefed issues sort by nQFactSequence first; unprefed
   *  fall back to nSequence. Empty claims are dropped so the panel doesn't
   *  render hollow headers.
   *
   *  Once any real issue exists, the Unassigned bucket is dropped from the
   *  picker — the user no longer needs the implicit fallback, and seeing it
   *  alongside concrete claims is noise. */
  visibleGroups = computed<IssueGroup[]>(() => {
    const all = this.groups();
    const realExist = this.hasRealIssues();
    const N = QFactIssuePanelComponent.DEFAULT_VISIBLE_PER_CLAIM;

    return all
      .filter(g => !(realExist && g.isUnassigned))
      .map(g => {
        // Compute the default-rule "first N" set up front, ranked by the
        // shared Fact-side nSequence so unprefed users see a deterministic
        // order regardless of the order the API returned issues in.
        const firstN = [...g.issues]
          .sort((a, b) => (a.nSequence ?? 0) - (b.nSequence ?? 0))
          .slice(0, N);
        const firstNIds = new Set(firstN.map(iss => iss.nIid));

        const visible = g.issues.filter(iss => {
          // The system Unassigned issue under the Unassigned claim is
          // pinned and always visible inside its own bucket — it's the
          // implicit fallback for QFacts captured without an explicit
          // issue, and we only ever reach this branch when no real issue
          // exists (the bucket itself is filtered out above otherwise).
          if (g.isUnassigned && iss.cIName === 'Unassigned') return true;
          if (iss.bQFactVisible === false) return false;
          if (iss.bQFactVisible === true) return true;
          return firstNIds.has(iss.nIid);
        });

        // Order: Unassigned issue first inside the Unassigned claim,
        // then nQFactSequence asc (set values first), then nSequence asc.
        visible.sort((a, b) => {
          if (g.isUnassigned) {
            const aU = a.cIName === 'Unassigned';
            const bU = b.cIName === 'Unassigned';
            if (aU !== bU) return aU ? -1 : 1;
          }
          const aQ = a.nQFactSequence;
          const bQ = b.nQFactSequence;
          if (aQ != null && bQ != null) return aQ - bQ;
          if (aQ != null) return -1;
          if (bQ != null) return 1;
          return (a.nSequence ?? 0) - (b.nSequence ?? 0);
        });

        return { ...g, issues: visible };
      })
      .filter(g => g.issues.length > 0);
  });

  /** First Unassigned-group issue, if the case has one. Used as the implicit
   *  default selection when the user hasn't picked anything yet AND there
   *  are no real issues to choose from — once a real issue exists, this
   *  returns null so the picker stops auto-falling-back to Unassigned. */
  unassignedIssue = computed<issueListRes | null>(() => {
    if (this.hasRealIssues()) return null;
    const u = this.groups().find(g => g.isUnassigned);
    return u?.issues?.[0] ?? null;
  });

  /** Same lookup as `unassignedIssue` but unconditional — always returns the
   *  case's system Unassigned issue (under the Unassigned claim) regardless
   *  of whether real issues also exist. The host (pdf.component) reads this
   *  to back-stop the QFact rapid-create flow: if the user highlights text
   *  in QFact mode without picking any issue from this panel, we silently
   *  attach the highlight to Unassigned instead of opening the side
   *  fact-creation panel — matches the UX brief's "highlight → done" goal.
   *
   *  Kept separate from `unassignedIssue` so the visible "default chip"
   *  affordance still hides once real issues exist (otherwise the bucket
   *  would always show as preselected even after the user has tagged
   *  something), while the silent rapid-create back-stop is always
   *  available. */
  caseUnassignedIssue = computed<issueListRes | null>(() => {
    const u = this.groups().find(g => g.isUnassigned);
    return u?.issues?.find(i => i.cIName === 'Unassigned') ?? u?.issues?.[0] ?? null;
  });

  /** What the panel highlights as "selected": explicit picks (filtered to
   *  currently-visible ids so a stale Unassigned chip from before real
   *  issues existed silently drops off), else the default Unassigned
   *  fallback when nothing is picked and the case has no real issues. */
  effectiveSelection = computed<string[]>(() => {
    const visibleIds = new Set(
      this.visibleGroups().flatMap(g => g.issues.map(i => i.nIid))
    );
    const explicit = this.sa.qfactSelected().filter(id => visibleIds.has(id));
    if (explicit.length) return explicit;
    const u = this.unassignedIssue();
    return u ? [u.nIid] : [];
  });

  selectedCount = computed(() => this.effectiveSelection().length);

  /** Resolved issue records matching `effectiveSelection`. The host (pdf.component)
   *  feeds these into its existing `selectedIssues` field so the QFact submit
   *  path (factService.submitQuickFact) tags the new QFact correctly. */
  effectiveSelectedIssues = computed<issueListRes[]>(() => {
    const ids = this.effectiveSelection();
    const all = this.groups().flatMap(g => g.issues);
    return ids.map(id => all.find(i => i.nIid === id)).filter((x): x is issueListRes => !!x);
  });

  /** Resolve the user's currently-picked issue IDs (from the service signal)
   *  to full records via the panel's RAW groups, bypassing the visibility
   *  filter that `effectiveSelection` applies. The visibility filter exists
   *  to drop stale Unassigned chips when real issues are added later — but
   *  it also drops legitimate picks while `visibleGroups` is still
   *  recomputing (right after the user toggles a real issue, the
   *  `bQFactVisible` recomputation can race the storage-sync that brings the
   *  pick into the iframe). For the rapid-create submit path the user's
   *  *intent* is what matters: if they picked an issue ID, that's what the
   *  new QFact should tag, regardless of whether the visibility computation
   *  has caught up yet. */
  resolvePickedFromRawGroups(): issueListRes[] {
    const ids = this.sa.qfactSelected();
    if (!ids.length) return [];
    const all = this.groups().flatMap(g => g.issues);
    return ids.map(id => all.find(i => i.nIid === id)).filter((x): x is issueListRes => !!x);
  }

  /** Visible chips: up to 6 fit in the 3×2 grid. When more than 6 are
   *  selected we cap at 5 so the 6th cell can host the "+N" overflow chip,
   *  keeping the header to exactly two rows. */
  displayedSelected = computed<issueListRes[]>(() => {
    const issues = this.effectiveSelectedIssues();
    return issues.length > 6 ? issues.slice(0, 5) : issues;
  });

  /** Emits whenever the resolved selection changes. Bound by the host so its
   *  `selectedIssues` field stays current — the QFact auto-fire on text
   *  selection reads that field, not the panel's signal directly. */
  @Output() selectedIssuesChange = new EventEmitter<issueListRes[]>();

  private refreshSub?: Subscription;

  constructor(
    public sa: SelectionActionsService,
    private issueService: IssueService,
    private tost: TostbarService,
  ) {
    effect(() => {
      const issues = this.effectiveSelectedIssues();
      // untracked so emitting doesn't re-trigger this effect via downstream
      // signal updates in the host.
      untracked(() => this.selectedIssuesChange.emit(issues));
    });
  }

  ngOnInit(): void {
    if (this.nCaseid && this.nUserid) {
      void this.loadIssues();
    }
    // When Manage Claims & Issues' QFact-mode batch flush completes, the
    // service emits on this stream so we re-fetch and pick up the new
    // bQFactVisible / nQFactSequence values without a page refresh.
    this.refreshSub = this.sa.qfactRefresh$.subscribe(() => {
      if (this.nCaseid && this.nUserid) void this.loadIssues();
    });
  }

  ngOnDestroy(): void {
    this.refreshSub?.unsubscribe();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if ((changes['nCaseid'] && !changes['nCaseid'].firstChange)
      || (changes['nUserid'] && !changes['nUserid'].firstChange)) {
      void this.loadIssues();
    }
  }

  async loadIssues(): Promise<void> {
    this.loading.set(true);
    try {
      const result = await this.issueService.fetchIssueListV2({
        nCaseid: this.nCaseid,
        nSessionid: this.nSesid || 'null',
        nIDid: 'null',
        nUserid: this.nUserid,
      });
      const categories: categoryList[] = result?.[0] ?? [];
      const issues: issueListRes[] = result?.[1] ?? [];

      // Iterate res[0] (categories) so the panel matches the Manage Claims &
      // Issues sidebar exactly — same set, same order. The previous approach
      // of grouping res[1] by nICid silently dropped any category that had no
      // matching issue and re-sorted alphabetically, which made claims look
      // missing on this side even though they were present on the other.
      const knownICids = new Set<string>();
      const groups: IssueGroup[] = categories.map(cat => {
        knownICids.add(cat.nICid);
        return {
          nICid: cat.nICid,
          cCategory: cat.cCategory,
          isUnassigned: cat.cCategory === 'Unassigned',
          issues: issues.filter(iss => iss.nICid === cat.nICid),
          nSequence: cat.nSequence,
          nQFactSequence: cat.nQFactSequence ?? null,
        };
      });

      // Defensive fallback: if any issue references an nICid that isn't in
      // res[0] (data drift), still surface it as its own group so the user
      // can pick it instead of having it vanish.
      const orphans = new Map<string, IssueGroup>();
      for (const iss of issues) {
        if (knownICids.has(iss.nICid)) continue;
        if (!orphans.has(iss.nICid)) {
          orphans.set(iss.nICid, {
            nICid: iss.nICid,
            cCategory: iss.cCategory,
            isUnassigned: iss.cCategory === 'Unassigned',
            issues: [],
          });
        }
        orphans.get(iss.nICid)!.issues.push(iss);
      }
      groups.push(...Array.from(orphans.values()));

      // Pin Unassigned to the top, then order by per-user nQFactSequence
      // (set values first), falling back to the shared Fact-side nSequence
      // for claims the user has not reordered in QFact mode.
      groups.sort((a, b) => {
        if (a.isUnassigned !== b.isUnassigned) return a.isUnassigned ? -1 : 1;
        const aQ = a.nQFactSequence;
        const bQ = b.nQFactSequence;
        if (aQ != null && bQ != null) return aQ - bQ;
        if (aQ != null) return -1;
        if (bQ != null) return 1;
        return (a.nSequence ?? 0) - (b.nSequence ?? 0);
      });

      this.groups.set(groups);
    } catch (e) {
      console.error('Failed to load QFact issues', e);
      this.groups.set([]);
    } finally {
      this.loading.set(false);
    }
  }

  isSelected(nIid: string): boolean {
    return this.effectiveSelection().includes(nIid);
  }

  toggle(nIid: string): void {
    this.sa.toggleQFactIssue(nIid);
  }

  clearAll(): void {
    this.sa.clearQFactIssues();
  }

  manage(): void {
    // Replaces the old standalone ManageIssuesDialogComponent popup —
    // the host (pdf.component / transcript-viewer / individual-doc)
    // listens on this stream and opens the existing `issue-manage` side
    // panel with QFact mode pre-enabled. Single source of truth for
    // claims / issues management.
    this.sa.requestOpenQFactManage();
  }
}
